def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after first '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert to comparable form: (is_numeric, numeric_value or string)
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, parsed_prerelease)

    def compare_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # For sorting:
        # 1. Compare major, minor, patch numerically
        # 2. Version without pre-release sorts after version with pre-release
        #    So if prerelease is None, we want it to sort later
        # 3. Pre-release identifiers compared as specified

        if prerelease is None:
            # No pre-release: sort after any pre-release version
            return (major, minor, patch, (1,))
        else:
            # Has pre-release: sort before non-pre-release
            return (major, minor, patch, (0, tuple(prerelease)))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

